// demo/household.ts
//
// The demo household: an invented family the tests,
// the guide's screenshots and the "Try it with sample data" start all draw from. Every
// name, employer, bank, shop, account tail and amount here is made up. National merchants
// (groceries, fuel, streaming, a warehouse club) appear by name so the starter rules can be
// shown working; every other shop is invented. No regional chain, no religious marker.
//
// Amounts are integer cents, always whole dollars or 50 cents, so none can pass for a real
// figure. The year of transactions is generated by rule from a fixed seed: buildDemo()
// returns the same data on every run and every machine.
//
// What the app can store today, and what it cannot yet:
// - accounts, transactions, the budget year and its every-month lines, the salary (with its
//   pay schedule and benefits), the charity pot (its name, kind and percent), the pot account
//   flag, balances and the two what-ifs all map onto existing repository methods and
//   settings (demo/build-sample-db.ts writes them).
// - The yearly bills and the raises have no storage yet.
//   They stay plain typed data here; the yearly bills already show up as transactions in
//   their months.
// - The people (names, the child) have no storage yet beyond the account owner tag and the
//   child count in the salary settings.
import type { Account, NormalizedTxn } from "../src/domain/types.js";
import type { BudgetLine, Plan } from "../src/domain/plan-types.js";
import type { CurrentSalary } from "../src/domain/income.js";
import type { PaySchedule } from "../src/domain/paycheck.js";
import type { Benefit } from "../src/domain/benefits.js";
import type { FilingStatus } from "../src/domain/tax.js";
import type { WhatIf } from "../src/domain/what-if.js";
import type { Household } from "../src/domain/household.js";

// ---------------------------------------------------------------------------------------
// Types. Where the app has a type, DEMO uses it; the rest are plain data for later lanes.
// ---------------------------------------------------------------------------------------

export interface DemoPerson {
  id: string;
  firstName: string;
  lastName: string;
  role: "adult" | "child";
  /** The app's account owner slot for an adult ("me" is the person using the app). */
  ownerTag: "me" | "partner" | null;
}

export interface DemoAccount {
  account: Account;
  /** The invented last four digits, also shown at the end of the account name. */
  tail: string;
  /** Balance before the first demo transaction, cents (cards: what is owed, as a negative). */
  openingBalanceCents: number;
}

/** The charity pot, in the demo's own shape (tests/demo.ts demoCharityPot gives the app's). */
export interface DemoPot {
  on: boolean;
  name: string;
  kind: "percent" | "monthly" | "yearly";
  /** For "percent": the percent of take-home pay (5 means 5%). For "monthly" and "yearly": cents. */
  amount: number;
  /** The account flagged as the pot. */
  accountId: string;
}

export interface DemoSalary {
  employer: string;
  current: CurrentSalary;
  paySchedule: PaySchedule;
  /** What lands in checking each payday, cents. */
  takeHomePerPaycheckCents: number;
  /** Paydays in each month: the 15th and the last day. */
  paydays: ["15th", "last"];
  benefits: Benefit[];
  /** How the household files federal income tax. */
  filingStatus: FilingStatus;
  children: number;
}

/** A bill paid once a year. No storage yet. */
export interface DemoYearlyBill {
  name: string;
  planningCategory: string;
  merchant: string;
  accountId: string;
  amountCents: number;
  /** 1 to 12. */
  month: number;
  day: number;
}

/** A raise tied to a US national holiday. No storage yet. */
export interface DemoRaise {
  holiday: "New Year's Day" | "Memorial Day" | "Independence Day" | "Labor Day" | "Thanksgiving Day";
  /** The holiday's date in the raise's year: the raise starts with the first paycheck after it. */
  date: string;
  newGrossAnnualCents: number;
}

export interface DemoWhatIf {
  name: string;
  whatIf: WhatIf;
}

export interface DemoHousehold {
  householdName: string;
  people: DemoPerson[];
  institutions: string[];
  accounts: DemoAccount[];
  salary: DemoSalary;
  pot: DemoPot;
  plan: Omit<Plan, "createdAt">;
  /** Every-month budget lines for the plan. */
  budgetLines: BudgetLine[];
  yearlyBills: DemoYearlyBill[];
  raises: DemoRaise[];
  whatIfs: DemoWhatIf[];
  /** First month of transactions, YYYY-MM. */
  firstMonth: string;
  /** Months of transactions in DEMO.transactions. */
  months: number;
  transactions: NormalizedTxn[];
}

