function account(
  id: string, name: string, tail: string, type: string, institution: string, owner: Account["owner"],
  openingBalanceCents: number, extra: Partial<Account> = {},
): DemoAccount {
  return {
    account: { id, name: `${name} ...${tail}`, type, institution, currency: "USD", isOwned: true, includeInSpend: true, owner, ...extra },
    tail,
    openingBalanceCents,
  };
}

