// ---------------------------------------------------------------------------------------
// The transaction generator: fixed rules, one seeded random stream.
// ---------------------------------------------------------------------------------------

/** mulberry32: a small seeded generator, so the same seed gives the same year everywhere. */
function seeded(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function monthAt(first: string, i: number): string {
  const [y, m] = first.split("-").map(Number);
  const n = y * 12 + (m - 1) + i;
  return `${Math.floor(n / 12)}-${String((n % 12) + 1).padStart(2, "0")}`;
}

function lastDay(ym: string): number {
  const [y, m] = ym.split("-").map(Number);
  return new Date(Date.UTC(y, m, 0)).getUTCDate();
}

const day = (ym: string, d: number) => `${ym}-${String(d).padStart(2, "0")}`;

const GROCERS = ["Walmart", "Whole Foods Market", "Trader Joe's", "Aldi"];
const FUEL = ["Shell", "Chevron", "ExxonMobil"];
const RESTAURANTS = ["Juniper Street Diner", "Oak & Ember Pizza", "Saffron Garden Kitchen"];

/**
 * `months` months of transactions from `firstMonth`. Each month follows the same rules; the
 * seeded stream varies the everyday amounts. For one first month, month N is the same whatever
 * `months` is, because the stream is consumed month by month in order.
 */
export function generateTransactions(months: number = DEMO_MONTHS, firstMonth: string = DEMO_FIRST_MONTH): NormalizedTxn[] {
  const rand = seeded(DEMO_SEED);
  /** A seeded amount in 50-cent steps from minDollars to maxDollars, as a negative (spending). */
  const spend = (minDollars: number, maxDollars: number) => -(minDollars * 100 + 50 * Math.floor(rand() * ((maxDollars - minDollars) * 2 + 1)));
  /** A seeded whole-dollar amount in `step`-dollar steps. */
  const wholeSpend = (minDollars: number, maxDollars: number, step: number) =>
    -100 * (minDollars + step * Math.floor(rand() * (Math.floor((maxDollars - minDollars) / step) + 1)));

  const out: NormalizedTxn[] = [];
  const cardOwed: Record<string, number> = { [ACCOUNT_IDS.alexCard]: 0, [ACCOUNT_IDS.samCard]: 0 };

  for (let i = 0; i < months; i++) {
    const ym = monthAt(firstMonth, i);
    const month = Number(ym.slice(5));
    const end = lastDay(ym);
    let n = 0;
    const add = (accountId: string, d: number, amountCents: number, merchant: string, category: string, isTransfer = false) => {
      n++;
      out.push({
        sourceTransactionId: `demo-${ym}-${String(n).padStart(3, "0")}`,
        accountId, date: day(ym, d), amountCents, sourceCategory: category, merchant, isTransfer,
        sourceUpdatedAt: null, description: merchant, memo: merchant.toUpperCase(), payee: merchant, mcc: null, pending: false,
      });
      if (accountId in cardOwed && !isTransfer) cardOwed[accountId] += -amountCents;
    };
    const move = (from: string, to: string, d: number, cents: number, label: string, category = "Transfer") => {
      add(from, d, -cents, label, category, true);
      add(to, d, cents, label, category, true);
    };

    // Pay the cards last month's charges first, so this month's charges wait for next month.
    for (const card of [ACCOUNT_IDS.alexCard, ACCOUNT_IDS.samCard]) {
      if (cardOwed[card] > 0) move(ACCOUNT_IDS.checking, card, 25, cardOwed[card], "Lakeshore Example Credit Union card payment", "Credit Card Payment");
      cardOwed[card] = 0;
    }

    // Checking: pay, rent, child care, utilities, saving.
    for (const d of [15, end]) {
      add(ACCOUNT_IDS.checking, d, TAKE_HOME_PER_PAYCHECK_CENTS, `${EMPLOYER} Payroll`, "Paychecks");
      move(ACCOUNT_IDS.checking, ACCOUNT_IDS.giving, d, (TAKE_HOME_PER_PAYCHECK_CENTS * GIVING_PERCENT) / 100, "Set aside for Charity");
    }
    add(ACCOUNT_IDS.checking, 1, -210_000, "Maple Court Apartments", "Rent");
    add(ACCOUNT_IDS.checking, 3, -90_000, "Little Acorns Daycare", "Child Care");
    const winter = [12, 1, 2].includes(month) ? 40 : [6, 7, 8].includes(month) ? 30 : 0;
    add(ACCOUNT_IDS.checking, 18, wholeSpend(95 + winter, 120 + winter, 5), "Clearwater Power & Light", "Gas & Electric");
    add(ACCOUNT_IDS.checking, 20, -7_000, "Fiberlane Internet", "Internet & Cable");
    move(ACCOUNT_IDS.checking, ACCOUNT_IDS.savings, 2, 20_000, "Transfer to Rainy Day Savings");
    move(ACCOUNT_IDS.checking, ACCOUNT_IDS.brokerage, 2, 30_000, "Transfer to Ridgeline Individual Investing");
    move(ACCOUNT_IDS.checking, ACCOUNT_IDS.retirement, 2, 25_000, "Transfer to Ridgeline Retirement");
    add(ACCOUNT_IDS.savings, end, 1_200, "Pinecrest Example Bank", "Interest");

    // Alex's card: groceries, the warehouse club, fuel, phone, two streaming services.
    [4, 11, 18, 26].forEach((d, k) => add(ACCOUNT_IDS.alexCard, d, spend(60, 150), GROCERS[(i + k) % GROCERS.length], "Groceries"));
    add(ACCOUNT_IDS.alexCard, 9, spend(150, 260), "Costco", "Groceries");
    [7, 21].forEach((d, k) => add(ACCOUNT_IDS.alexCard, d, spend(35, 60), FUEL[(i + k) % FUEL.length], "Gas"));
    add(ACCOUNT_IDS.alexCard, 12, -1_600, "Netflix", "Entertainment & Recreation");
    add(ACCOUNT_IDS.alexCard, 14, -1_200, "Spotify", "Entertainment & Recreation");
    add(ACCOUNT_IDS.alexCard, 16, -8_500, "Brightwave Mobile", "Phone");

    // Sam's card: eating out, coffee, a store run, a streaming service, the odd clinic visit.
    [6, 13, 27].forEach((d, k) => add(ACCOUNT_IDS.samCard, d, spend(18, 65), RESTAURANTS[(i + k) % RESTAURANTS.length], "Restaurants & Bars"));
    for (const d of [3, 10, 17, 24]) add(ACCOUNT_IDS.samCard, d, spend(4, 9), "Corner Grind Coffee", "Coffee Shops");
    add(ACCOUNT_IDS.samCard, 19, spend(25, 90), "Target", "Shopping");
    add(ACCOUNT_IDS.samCard, 22, -1_000, "Disney+", "Entertainment & Recreation");
    if (month % 2 === 1) add(ACCOUNT_IDS.samCard, 8, -3_000, "Willowbend Family Clinic", "Medical");

    // The Charity pot: a monthly gift, and a larger one in December.
    add(ACCOUNT_IDS.giving, 20, -15_000, "Riverside Community Pantry", "Charity");
    if (month === 12) add(ACCOUNT_IDS.giving, 28, -50_000, "Lakeview Library Fund", "Charity");

    // Yearly bills, in their months.
    for (const b of YEARLY_BILLS) if (b.month === month) add(b.accountId, b.day, -b.amountCents, b.merchant, b.planningCategory);
  }
  return out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.sourceTransactionId < b.sourceTransactionId ? -1 : 1));
}

/** Labor Day: the first Monday of September. */
function laborDay(year: number): string {
  const first = new Date(Date.UTC(year, 8, 1)).getUTCDay();
  return `${year}-09-${String(1 + ((8 - first) % 7)).padStart(2, "0")}`;
}

export interface BuildDemoOptions {
  /** The last month of transactions, YYYY-MM. Default DEMO_END_MONTH. */
  endMonth?: string;
  /** Leave out transactions dated after this day, YYYY-MM-DD (a sample built mid-month). */
  through?: string;
}

/**
 * Builds the household: twelve months of transactions ending with `endMonth`, the budget year
 * that month falls in, and the what-ifs and raises in the year after. Pure: the same options
 * give deep-equal data.
 */
export function buildDemo({ endMonth = DEMO_END_MONTH, through }: BuildDemoOptions = {}): DemoHousehold {
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(endMonth)) throw new Error("The end month must be written YYYY-MM.");
  const firstMonth = monthAt(endMonth, 1 - DEMO_MONTHS);
  const year = Number(endMonth.slice(0, 4));
  const planId = `demo-${year}`;
  const transactions = generateTransactions(DEMO_MONTHS, firstMonth).filter((t) => through === undefined || t.date <= through);
  return {
    householdName: "The Rivera household",
    people: [
      { id: "alex", firstName: "Alex", lastName: "Rivera", role: "adult", ownerTag: "me" },
      { id: "sam", firstName: "Sam", lastName: "Rivera", role: "adult", ownerTag: "partner" },
      { id: "riley", firstName: "Riley", lastName: "Rivera", role: "child", ownerTag: null },
    ],
    institutions: ["Pinecrest Example Bank", "Lakeshore Example Credit Union", "Ridgeline Example Investments"],
    accounts: demoAccountList(),
    salary: {
      employer: EMPLOYER,
      current: { kind: "gross", grossAnnualCents: 9_600_000, fromPeriod: firstMonth },
      paySchedule: "twice-a-month",
      takeHomePerPaycheckCents: TAKE_HOME_PER_PAYCHECK_CENTS,
      paydays: ["15th", "last"],
      benefits: [
        { name: "Health insurance", amountCents: 15_000, every: "paycheck", beforeTax: true },
        { name: "Dental and vision", amountCents: 2_000, every: "paycheck", beforeTax: true },
      ],
      filingStatus: "mfj",
      children: 1,
    },
    pot: { on: true, name: "Charity", kind: "percent", amount: GIVING_PERCENT, accountId: ACCOUNT_IDS.giving },
    plan: { id: planId, name: `${year} budget`, startDate: `${year}-01-01`, endDate: `${year}-12-31` },
    budgetLines: BUDGET.map(([planningCategory, amountCents]) => ({ planId, planningCategory, period: null, amountCents, source: "you" as const })),
    yearlyBills: YEARLY_BILLS.map((b) => ({ ...b })),
    raises: [
      { holiday: "New Year's Day", date: `${year + 1}-01-01`, newGrossAnnualCents: 10_000_000 },
      { holiday: "Labor Day", date: laborDay(year + 1), newGrossAnnualCents: 10_400_000 },
    ],
    whatIfs: whatIfs(year + 1),
    firstMonth,
    months: DEMO_MONTHS,
    transactions,
  };
}

export const DEMO: DemoHousehold = buildDemo();

/** The household's names as the app stores them: the adult tagged "me" and the one tagged "partner". */
export function householdOf(people: DemoPerson[]): Household {
  const named = (tag: DemoPerson["ownerTag"]) => people.find((p) => p.ownerTag === tag)?.firstName ?? null;
  return { youName: named("me") ?? "", partnerName: named("partner") };
}
